CREATE OR REPLACE FUNCTION topicLogits AS (emb) -> arrayMap(c -> dotProduct(dictGet('default.topic_lr_dict','w',c), l2normalize(emb)) + dictGet('default.topic_lr_dict','b',c), ['AI & Data','Careers & Work','Hardware & Systems','Other','Programming','Science & Health','Security & Privacy','Society & Politics','Startups & Business']);
CREATE OR REPLACE FUNCTION classifyTopic AS (emb) -> arrayElement(['AI & Data','Careers & Work','Hardware & Systems','Other','Programming','Science & Health','Security & Privacy','Society & Politics','Startups & Business'], indexOf(topicLogits(emb), arrayMax(topicLogits(emb))));
CREATE OR REPLACE FUNCTION topicProbs AS (emb) -> arrayMap(e -> e/arraySum(arrayMap(z->exp(z-arrayMax(topicLogits(emb))), topicLogits(emb))), arrayMap(z->exp(z-arrayMax(topicLogits(emb))), topicLogits(emb)));
